args <- commandArgs(trailingOnly = FALSE)
file_arg <- grep("^--file=", args, value = TRUE)
lab_dir <- if (length(file_arg)) dirname(normalizePath(sub("^--file=", "", file_arg[1]))) else normalizePath(getwd())
data_path <- function(name) file.path(lab_dir, "data", name)
out_path <- function(name) file.path(lab_dir, "outputs", name)
dir.create(out_path(""), recursive = TRUE, showWarnings = FALSE)
options(stringsAsFactors = FALSE)

h <- read.csv(data_path("health-research.csv")); f<-read.csv(data_path("feedback.csv"),fileEncoding="UTF-8-BOM")
control<-data.frame(control=c("Health rows","Feedback rows","Missing health values","Duplicate feedback IDs"),value=c(nrow(h),nrow(f),sum(is.na(h)),sum(duplicated(f$record_id))),status=c("PASS","PASS",ifelse(sum(is.na(h))==0,"PASS","REVIEW"),ifelse(anyDuplicated(f$record_id)==0,"PASS","REVIEW")))
m<-lm(weight~cancer_cell+smoker,h); sm<-summary(m); tt<-t.test(weight~smoker,h)
words<-unlist(strsplit(tolower(gsub("[^[:alpha:] ]"," ",paste(f$comment,collapse=" "))),"\\s+")); words<-words[nchar(words)>4]; tf<-sort(table(words),decreasing=TRUE)
summary_out<-data.frame(metric=c("Mean weight","Median weight","Correlation cancer_cell-weight","Regression R-squared","Smoking-group p-value","Top feedback term count"),value=c(mean(h$weight),median(h$weight),cor(h$cancer_cell,h$weight),sm$r.squared,tt$p.value,max(tf)))
write.csv(control,out_path("lab-10-control-log.csv"),row.names=FALSE); write.csv(summary_out,out_path("lab-10-analysis-summary.csv"),row.names=FALSE)
sensitivity<-data.frame(comparison=c("All records","Exclude highest cancer-cell observation"),correlation=c(cor(h$cancer_cell,h$weight),cor(h$cancer_cell[-which.max(h$cancer_cell)],h$weight[-which.max(h$cancer_cell)])))
write.csv(sensitivity,out_path("lab-10-sensitivity.csv"),row.names=FALSE)
png(out_path("lab-10-briefing.png"),1400,900,res=130); par(mfrow=c(2,2)); hist(h$weight,col="#CADCFC",border="white",main="Weight distribution",xlab="kg"); boxplot(weight~smoker,h,col=c("#1F6FEB","#10B981"),main="Weight by smoking status"); plot(h$cancer_cell,h$weight,pch=19,col="#7C3AED",xlab="Cancer-cell indicator",ylab="Weight",main="Observed relationship"); abline(lm(weight~cancer_cell,h),col="#DC2626",lwd=2); barplot(head(tf,8),las=2,col="#F59E0B",main="Frequent feedback terms"); dev.off()
writeLines(capture.output(sessionInfo()),out_path("lab-10-session-info.txt")); stopifnot(all(control$status=="PASS")); cat("Lab 10 complete\n")
